import React from 'react';
import { motion } from 'framer-motion';
import { BRAND } from '../../config/brand';

/**
 * Premium Brand Logo Component
 * 
 * Props:
 * - variant: "full" (symbol+wordmark), "symbol" (icon only)
 * - className: additional classes
 * - layoutId: for framer-motion shared transitions (e.g. from preloader)
 * - animated: true if it should pulse or have hover effects
 */
export default function Logo({ variant = 'full', className = '', layoutId, animated = false }) {
  // We use the webp versions generated by our sharp script
  // Fallback to png if webp fails
  
  const imgProps = {
    src: "/brand/logo-512.webp",
    alt: `${BRAND.fullName} - ${BRAND.tagline}`,
    className: `object-contain ${className}`,
    onError: (e) => {
      // Fallback to original if missing
      e.target.onerror = null; 
      e.target.src = '/logo.png';
    }
  };

  const content = (
    <div className={`flex items-center gap-2 ${variant === 'symbol' ? 'justify-center' : ''}`}>
      {/* On dark mode, if not in a white badge, the white stroke usually looks fine, 
          but as per instructions, it's safe to add a subtle white glow if needed. */}
      <img 
        {...imgProps} 
        className={`w-10 h-10 sm:w-12 sm:h-12 drop-shadow-md ${animated ? 'hover:scale-105 transition-transform' : ''} ${imgProps.className}`}
      />
      
      {variant === 'full' && (
        <div className="flex flex-col">
          <span className="text-xl font-black tracking-tight leading-none text-transparent bg-clip-text bg-gradient-to-r from-brand-600 to-red-400">
            {BRAND.name}
          </span>
          <span className="text-[0.65rem] font-bold text-gray-500 tracking-widest uppercase mt-0.5 hidden sm:block">
            .{BRAND.domain}
          </span>
        </div>
      )}
    </div>
  );

  return content;
}
